// Example: simple local DP noise for a numeric metric
function addLaplaceNoise(x, b) {
  const u = Math.random() - 0.5;
  const noise = -b * Math.sign(u) * Math.log(1 - 2 * Math.abs(u));
  return x + noise;
}
